import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Local docs and Pages","description":"Run the VitePress site locally and publish it to GitHub Pages without changing application infrastructure.","frontmatter":{"title":"Local docs and Pages","description":"Run the VitePress site locally and publish it to GitHub Pages without changing application infrastructure."},"headers":[],"relativePath":"project/setup.md","filePath":"project/setup.md","lastUpdated":1794433168000}'),n={name:"project/setup.md"};function o(r,e,l,h,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="run-and-publish-the-documentation" tabindex="-1">Run and publish the documentation <a class="header-anchor" href="#run-and-publish-the-documentation" aria-label="Permalink to &quot;Run and publish the documentation&quot;">​</a></h1><p>This procedure affects only documentation. It does not deploy the research application or change portfolio DNS.</p><h2 id="local-preview" tabindex="-1">Local preview <a class="header-anchor" href="#local-preview" aria-label="Permalink to &quot;Local preview&quot;">​</a></h2><p>Use Node.js 22+; Python 3.10+ is also needed for <code>npm test</code>. Preserve existing checkout changes rather than cloning over them.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Projects&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kaw393939/is373-rag.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Projects/is373-rag&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Projects/is373-rag&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open the displayed address, including <code>/is373-rag/</code>. No model or API key is required. An assistant checkout under <code>/mnt/data</code> is not a folder on your Mac.</p><h2 id="verify-the-site" tabindex="-1">Verify the site <a class="header-anchor" href="#verify-the-site" aria-label="Permalink to &quot;Verify the site&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>The checks cover synthetic examples, plan consistency, the VitePress build, generated links/anchors/assets/sitemap and documentation navigation. The separate Rust lab command is in <a href="./../engineering/clean-build">clean builds</a>. Browser, keyboard and assistive-technology checks are additional evidence.</p><h2 id="public-github-pages-mirror" tabindex="-1">Public GitHub Pages mirror <a class="header-anchor" href="#public-github-pages-mirror" aria-label="Permalink to &quot;Public GitHub Pages mirror&quot;">​</a></h2><p>The same VitePress source is now served through the existing portfolio Pages site at <strong><a href="https://kaw393939.github.io/knowledge-lab/" target="_blank" rel="noreferrer">kaw393939.github.io/knowledge-lab/</a></strong>. The portfolio&#39;s <a href="https://github.com/kaw393939/kaw393939.github.io/blob/main/scripts/build-knowledge-lab.mjs" target="_blank" rel="noreferrer">build script</a> checks out a pinned commit from this repository, builds with <code>DOCS_BASE=/knowledge-lab/</code>, checks generated routes and references, then publishes the combined static site. The <a href="https://github.com/kaw393939/kaw393939.github.io/actions/workflows/publish.yml" target="_blank" rel="noreferrer">portfolio publishing workflow</a> owns that release.</p><p><strong>Keep one source of truth:</strong> change the docs here, pass this repository&#39;s tests, then update the approved source SHA in the portfolio build script and its verifier to promote a new documentation release. Do not maintain a second, diverging Markdown textbook in the portfolio repository.</p><p>The <a href="https://kaw393939.github.io/is373-rag/" target="_blank" rel="noreferrer">standalone project site</a> is enabled with GitHub Actions and publishes from this repository. This mirror does <strong>not</strong> deploy the Rust research application, change DNS, or expose student data.</p><h2 id="standalone-project-pages-configuration" tabindex="-1">Standalone project Pages configuration <a class="header-anchor" href="#standalone-project-pages-configuration" aria-label="Permalink to &quot;Standalone project Pages configuration&quot;">​</a></h2><p>For a new fork or recovery, open <a href="https://github.com/kaw393939/is373-rag/settings/pages" target="_blank" rel="noreferrer">this repository&#39;s Pages settings</a>. Under <strong>Build and deployment → Source</strong>, select <strong>GitHub Actions</strong>. Then open the <a href="https://github.com/kaw393939/is373-rag/actions/workflows/docs.yml" target="_blank" rel="noreferrer">Documentation workflow</a> and run it on <code>main</code>.</p><p>The workflow needs an already enabled Pages site. GitHub&#39;s ordinary Actions token cannot perform first-time administrative enablement. Do not paste a personal token into a chat or commit one to work around that boundary.</p><h2 id="what-standalone-publication-verifies" tabindex="-1">What standalone publication verifies <a class="header-anchor" href="#what-standalone-publication-verifies" aria-label="Permalink to &quot;What standalone publication verifies&quot;">​</a></h2><p>Pull requests build previews without deploying. A main-branch run builds, tests, uploads only <code>dist/</code>, deploys to Pages and checks the actual public homepage, vision, glossary and stylesheet. The response must identify the expected source revision.</p><p>An unavailable or incorrectly configured Pages source <strong>fails the publication job</strong>. It no longer produces a green skipped deployment. The successful build artifact remains available even when publication is blocked.</p><p>Default address: <code>https://kaw393939.github.io/is373-rag/</code>. The Pages action&#39;s actual URL is authoritative. The workflow reads an existing Pages address before building, so a later account-level domain change does not require hard-coded origin edits. This repository does not create a <code>CNAME</code> or change DNS.</p><h2 id="ongoing-updates" tabindex="-1">Ongoing updates <a class="header-anchor" href="#ongoing-updates" aria-label="Permalink to &quot;Ongoing updates&quot;">​</a></h2><p>Edit Markdown, retain canonical requirement links, run tests and merge a reviewed PR. Successful main updates publish automatically after activation. <a href="./../reference/documentation-map">Documentation editing rules</a>.</p><p><code>DOCS_BASE</code> defaults to <code>/is373-rag/</code>; <code>DOCS_ORIGIN</code> defaults to <code>https://kaw393939.github.io</code> for local and not-yet-enabled previews. CI overrides them from existing Pages metadata when available. The <code>source-checkout</code> artifact contains a Git bundle; use the matching main-run artifact when an offline checkout is needed.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><p>Never commit credentials, private source data, student records or generated runtime state. Pages serves static docs—not the chat API, scheduler or model. Application hosting remains a <a href="./hosting">separate operation</a>.</p><p>References: <a href="https://vitepress.dev/guide/deploy" target="_blank" rel="noreferrer">VitePress deployment</a>, <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages" target="_blank" rel="noreferrer">GitHub Pages workflows</a>, <a href="https://github.com/actions/configure-pages/blob/v5/action.yml" target="_blank" rel="noreferrer">first-time enablement permissions</a>.</p>`,26)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
